    if (!el || el.hidden) return false;
    var ev = new CustomEvent('sg:dismiss', { bubbles: true, cancelable: true });
    if (!el.dispatchEvent(ev)) return false;
    var target = el.contains(document.activeElement) ? neighbour(el) : null;
