      'M' + (cx - r1) + ' ' + cy + 'A' + r1 + ' ' + r1 + ' 0 1 0 ' + (cx + r1) + ' ' + cy + 'A' + r1 + ' ' + r1 + ' 0 1 0 ' + (cx - r1) + ' ' + cy + 'Z';
