    4: '<path d="M0 0L8 8M-1 7L1 9M7 -1L9 1"/>',
    5: '<path d="M0 8L8 0M0 0L8 8M-1 1L1 -1M7 9L9 7M-1 7L1 9M7 -1L9 1"/>',
