/* ===== src/js/73-agenda.js ===== */
/* ==========================================================================
   SG.agenda: where each event goes on a day's time grid
   --------------------------------------------------------------------------
   The agenda is markup and CSS; an event is placed by four numbers on its <li>:
   --from and --to (grid lines, one every 15 minutes), --lane and --span (columns).
   Working those out is the only hard part of a day view, so here it is, as a pure
   function: no DOM, runs anywhere.

     SG.agenda.layout(events, { start: 540 })
       events   [{ start: 570, end: 600, ...anything }]   minutes after midnight
       start    the minute the grid's first line is (default: the earliest event's hour)
       end      the minute the grid ends (default: the latest event's end, rounded up to the hour)
     returns    { lanes, steps, start, end, items: [{ ...event, from, to, lane, span }] }

   Events that overlap, directly or through a chain of other events, form a cluster. In a cluster each
   event takes the first lane that is free when it starts. An event alone in its cluster spans every
   lane, so a quiet hour uses the full width; in a cluster of k lanes each event spans floor(lanes / k).
   Items come back in start order (then longest first), which is also the order they should appear
   in the DOM, so reading order and tab order are chronological whatever the lanes look like.

     lanes   the most events that ever overlap: put it on the .agenda-day as data-lanes and --lanes
     steps   the number of 15-minute rows: put it on the .agenda-day as --steps

   SG.agenda.minutes('09:30') -> 570        SG.agenda.time(570) -> '9:30'
   ========================================================================== */
(function (SG) {
  'use strict';

  var STEP = 15;

  function minutes(hhmm) {
    var m = /^(\d{1,2}):(\d{2})$/.exec(hhmm);
    return m ? +m[1] * 60 + +m[2] : NaN;
  }

  function time(min) {
    var h = Math.floor(min / 60), m = min % 60;
    return h + ':' + (m < 10 ? '0' : '') + m;
  }

  function layout(events, opts) {
    var o = opts || {};
    var list = events.map(function (e, i) { return Object.assign({}, e, { _i: i }); });
    list.sort(function (a, b) { return a.start - b.start || (b.end - b.start) - (a.end - a.start) || a._i - b._i; });

    // clusters: consecutive events while each starts before the cluster's latest end
    var clusters = [], cur = null;
    list.forEach(function (e) {
      if (!cur || e.start >= cur.end) { cur = { items: [], end: e.end, lanes: [] }; clusters.push(cur); }
      cur.end = Math.max(cur.end, e.end);
      cur.items.push(e);
      var lane = 0;
      while (cur.lanes[lane] !== undefined && cur.lanes[lane] > e.start) lane++;
      cur.lanes[lane] = e.end;
      e.lane = lane + 1;
    });

    var lanes = clusters.reduce(function (m, c) { return Math.max(m, c.lanes.length); }, 1);
    var first = list.length ? Math.min.apply(null, list.map(function (e) { return e.start; })) : 0;
    var last = list.length ? Math.max.apply(null, list.map(function (e) { return e.end; })) : 0;
    var start = o.start != null ? o.start : Math.floor(first / 60) * 60;
    var end = o.end != null ? o.end : Math.ceil(last / 60) * 60;

    clusters.forEach(function (c) {
      var k = c.lanes.length;
      var span = Math.max(1, Math.floor(lanes / k));
      c.items.forEach(function (e) {
        e.span = span;
        e.lane = (e.lane - 1) * span + 1;
        e.from = Math.floor((e.start - start) / STEP) + 1;
        e.to = Math.max(e.from + 1, Math.ceil((e.end - start) / STEP) + 1);
        delete e._i;
      });
    });

    return { lanes: lanes, steps: Math.max(0, Math.ceil((end - start) / STEP)), start: start, end: end, items: list };
  }

  SG.agenda = { layout: layout, minutes: minutes, time: time };
})((typeof window !== 'undefined' ? (window.SG = window.SG || {}) : (globalThis.SG = globalThis.SG || {})));

/* ===== src/js/73-timeline.js ===== */
/* ==========================================================================
   SG.timeline: playhead, clip listbox, split / trim, ruler and zoom for .timeline
   --------------------------------------------------------------------------
   Markup and the reasoning are in src/components/timeline.css. The model is the DOM:
   a clip's place in time is its inline custom properties (--start, --dur, optionally
   --in for where in the source it begins), the playhead's is --t on .timeline__playhead,
   the length is --total on .timeline__body. All in SECONDS. Nothing is kept in script.

   KEYBOARD (playhead = role="slider", WAI-ARIA slider pattern)
     Left / Right          back / forward one step (data-step on .timeline, default 1 s)
     PageDown / PageUp     ten steps
     Home / End            start / end
   KEYBOARD (a track = role="listbox", WAI-ARIA listbox pattern, roving tabindex)
     Left / Right          previous / next clip (focus only)
     Home / End            first / last clip
     Enter / Space         select the focused clip
   POINTER: drag the head, or CLICK the ruler or empty track to put the playhead there
   (the click is the alternative to dragging, WCAG 2.5.7). Click a clip to select it.
   BUTTONS (data-timeline="…"): back, forward, split, trim-start, trim-end, zoom-in, zoom-out. Put each tool's word
   in a <span class="timeline__word">: the bar's layout (SG.fit, below) may show it, or keep it only as the name.
   Split and trim act on the selected clip at the playhead. They are aria-disabled, not
   disabled, when they cannot act, and the reason is in .timeline__hint (aria-describedby),
   so focus is never lost when the last useful press lands.

   EVENTS on .timeline (bubbling)
     sg:timeline-seek     { time }                     after the playhead moved
     sg:timeline-action   { action, clip, time }       BEFORE split / trim; preventDefault() to
                                                       own the change (your model) and skip ours
     sg:timeline-change   { action, clip }             after we changed the DOM
   API: SG.timeline.init(el), .setTime(el, seconds), .select(el, clip), .refresh(el)
   ========================================================================== */
